  'Azerbaijan': ['亞塞拜然', '阿塞拜疆'],
  'Georgia': ['喬治亞', '格魯吉亞'],
  'Philippines': ['菲律賓'],
  'Malaysia': ['馬來西亞'],
  'Slovenia': ['斯洛維尼亞', '斯洛文尼亞'],
  'Finland': ['芬蘭'],
  'Slovakia': ['斯洛伐克'],
  'Czechia': ['捷克', 'Czech Republic'],
  'Eritrea': ['厄利垂亞', '厄立特里亞'],
  'Japan': ['日本'],
  'Paraguay': ['巴拉圭'],
  'Yemen': ['葉門', '也門'],
  'Saudi Arabia': ['沙烏地阿拉伯', '沙特阿拉伯', '沙國'],
  'Antarctica': ['南極洲', '南極'],
  'Morocco': ['摩洛哥'],
  'Egypt': ['埃及'],
  'Libya': ['利比亞'],
  'Ethiopia': ['衣索比亞', '埃塞俄比亞'],
  'Djibouti': ['吉布地', '吉布提'],
  'Somaliland': ['索馬利蘭', '索馬里蘭'],
  'Uganda': ['烏干達'],
  'Rwanda': ['盧安達', '盧旺達'],
  'Bosnia and Herz.': ['波士尼亞', '波黑', 'Bosnia', 'Bosnia and Herzegovina'],
  'Macedonia': ['北馬其頓', '馬其頓', 'North Macedonia'],
  'Serbia': ['塞爾維亞'],
